INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7434378, 1175078, 108069, '<td valign="top">Love Munich. Great vantage point.</td>', 'Love Munich. Great vantage point.', '2016-02-03 00:05:42.000000', NULL, 1),
(7434391, 1175051, 30861, '<td valign="top">If this is Ramona, it must be Jean?</td>', 'If this is Ramona, it must be Jean?', '2016-02-03 00:38:37.000000', NULL, 1),
(7434411, 1174851, 181756, '<td valign="top">This is a beautiful landscape!  Gallery quality.  It is one of the nicest images in the challenge.  But I don''t see the tonal contrasts and textures of an "HDR" image.  This challenge was a particularly difficult one to pull off, given the assignment and the varying views of what is or is not HDR.</td>', 'This is a beautiful landscape!  Gallery quality.  It is one of the nicest images in the challenge.  But I don''t see the tonal contrasts and textures of an "HDR" image.  This challenge was a particularly difficult one to pull off, given the assignment and the varying views of what is or is not HDR.', '2016-02-03 05:26:38.000000', NULL, 1),
(7434431, 1175371, 54446, '<td valign="top">Excellent presentation.  Magnificent scene.  This should be the Blue.  Really great control of the dynamic range.</td>', 'Excellent presentation.  Magnificent scene.  This should be the Blue.  Really great control of the dynamic range.', '2016-02-03 07:36:49.000000', NULL, 1),
(7434432, 1175350, 54446, '<td valign="top">Nice job.  Excellent control of tonal range.  Should be top 3.</td>', 'Nice job.  Excellent control of tonal range.  Should be top 3.', '2016-02-03 07:38:57.000000', NULL, 1),
(7434433, 1175316, 54446, '<td valign="top">Very wonderful image and outstanding use of HDR techniques.  This should finish in the top 3.</td>', 'Very wonderful image and outstanding use of HDR techniques.  This should finish in the top 3.', '2016-02-03 07:40:18.000000', NULL, 1),
(7434434, 1175234, 54446, '<td valign="top">This is well presented.  Very nice control of highlights and shadows.  Good clarity.</td>', 'This is well presented.  Very nice control of highlights and shadows.  Good clarity.', '2016-02-03 07:44:46.000000', NULL, 1),
(7434436, 1175004, 54446, '<td valign="top">Exceptionally fine presentation.  The highlights and shadows are just right.  This is an eye-pleasing image to me.</td>', 'Exceptionally fine presentation.  The highlights and shadows are just right.  This is an eye-pleasing image to me.', '2016-02-03 08:01:27.000000', NULL, 1),
(7434438, 1174851, 62357, '<td valign="top">Beautiful.  Best in class.</td>', 'Beautiful.  Best in class.', '2016-02-03 08:06:21.000000', NULL, 1),
(7434440, 1174851, 175066, '<td valign="top">Great capture of the moon...It looks so close. one of my top picks</td>', 'Great capture of the moon...It looks so close. one of my top picks', '2016-02-03 08:07:10.000000', NULL, 1),
(7434452, 1175316, 38032, '<td valign="top">The depth here great. Lovely use of HDR. My fave so far.</td>', 'The depth here great. Lovely use of HDR. My fave so far.', '2016-02-03 09:43:30.000000', NULL, 1),
