(7436111, 1175209, 29777, '<td valign="top">It is difficult for me to know the intended subject here. The bright chimney draws my eye but the sky takes up most of the frame.</td>', 'It is difficult for me to know the intended subject here. The bright chimney draws my eye but the sky takes up most of the frame.', '2016-02-09 21:14:01.000000', NULL, 1),
(7436112, 1175335, 68504, '<td valign="top">this is interesting. we know the sun is glaringly bright, but your hdr enables us to see what the son would have blinded us to. we ask if this is a good thing. good to ask questions.</td>', 'this is interesting. we know the sun is glaringly bright, but your hdr enables us to see what the son would have blinded us to. we ask if this is a good thing. good to ask questions.', '2016-02-09 21:14:28.000000', NULL, 1),
